import java.util.*;

class Solution {
    int[] acceptOrDeclineQueries(String[] timestamps, String[] ipAddresses, int limit, int timeWindow) {
        Map<String, TreeMap<Long, Integer>> accepted = new HashMap<>();
        int[] res = new int[timestamps.length];
        for (int i = 0; i < timestamps.length; i++) {
            long ts = Long.parseLong(timestamps[i]);
            String ip = ipAddresses[i];
            TreeMap<Long, Integer> tm = accepted.computeIfAbsent(ip, k -> new TreeMap<>());
            long lo = ts - timeWindow;
            int count = 0;
            for (Long t : tm.tailMap(lo).keySet()) count += tm.get(t);
            if (count < limit) {
                tm.merge(ts, 1, Integer::sum);
                res[i] = 1;
            } else res[i] = 0;
        }
        return res;
    }
}

#include <bits/stdc++.h>
using namespace std;

class Solution {
   public:
    vector<int> acceptOrDeclineQueries(vector<string>& timestamps, vector<string>& ipAddresses,
                                       int limit, int timeWindow) {
        unordered_map<string, vector<long long>> accepted;
        vector<int> res(timestamps.size());
        for (size_t i = 0; i < timestamps.size(); ++i) {
            long long ts = stoll(timestamps[i]);
            auto& lst = accepted[ipAddresses[i]];
            long long lo = ts - timeWindow;
            auto it = lower_bound(lst.begin(), lst.end(), lo);
            int count = lst.end() - it;
            if (count < limit) {
                lst.insert(upper_bound(lst.begin(), lst.end(), ts), ts);
                res[i] = 1;
            } else
                res[i] = 0;
        }
        return res;
    }
};
